const root=document.querySelector('#app');
const theme=document.body.dataset.theme;
const titles={dream:'Shared dreams',electric:'Split studio',blend:'The social ledger'};
root.innerHTML=`<a class="skip" href="#main">Skip to content</a><div class="shell"><header class="app-header"><a href="#dashboard" class="brand"><span class="brandmark" aria-hidden="true">bb</span>broYouOweMe</a><nav aria-label="Account" class="global-nav"><button data-screen="dashboard">My groups</button><button data-screen="settlements">My balances</button><span class="avatar" aria-label="Signed in as taral">TA</span></nav></header><nav class="prototype-nav" aria-label="Prototype screens"><button data-screen="dashboard" aria-pressed="true">Group dashboard</button><button data-screen="landing" aria-pressed="false">Landing page</button><button data-screen="expense" aria-pressed="false">Add expense</button><button data-screen="settlements" aria-pressed="false">Settle up</button></nav><main id="main" tabindex="-1">
<section class="screen" data-page="dashboard"><a href="#landing" class="back">← My groups</a><div class="page-head"><div><h1>Goa, with the gang.</h1><p><span class="members" aria-hidden="true"><span class="avatar">TA</span><span class="avatar">RI</span><span class="avatar">AR</span><span class="avatar">NE</span></span>4 members · All amounts in INR</p></div><div class="head-actions"><button data-screen="expense">＋ Add expense</button><button class="secondary" data-info="Invite links and QR codes remain admin-only in the app.">Invite friends</button></div></div><nav class="group-nav" aria-label="Group sections"><button aria-current="page" data-screen="dashboard">Overview</button><button data-screen="history">Expenses</button><button data-screen="settlements">Settlements</button><button data-info="Insights will use this shell with exact totals, month filters and accessible charts.">Insights</button><button data-info="Activity will use human dates and expandable change details.">Activity</button><button data-info="Members, categories, invites and reminders retain their existing permissions.">More</button></nav><div class="dashboard-grid"><div class="stack"><section class="panel"><div class="panel-head"><h2>Recent expenses</h2><button class="section-link" data-screen="history">View all</button></div><div class="toolbar"><input id="search" type="search" aria-label="Search expenses" placeholder="Search this trip’s expenses"><select id="category-filter" aria-label="Filter by category"><option value="">All categories</option><option>Food</option><option>Stay</option><option>Travel</option></select></div><ul class="receipt-list" id="expenses"></ul><p id="no-results" hidden>No expenses match. Try another search or category.</p></section><section class="panel"><div class="panel-head"><h2>The gang</h2><span class="small">4 members</span></div><div class="members" aria-hidden="true"><span class="avatar">TA</span><span class="avatar">RI</span><span class="avatar">AR</span><span class="avatar">NE</span></div><p class="small" style="margin:14px 0 0">taral (you, admin), riya, arjun, neha</p></section></div><div class="stack"><section class="panel summary"><p>Your group balance</p><strong class="money total">₹1,240.50</strong><p>You’re owed overall in this group</p><div class="mini-grid"><div><small>You paid</small><strong class="money">₹5,640.50</strong></div><div><small>Your share</small><strong class="money">₹4,400.00</strong></div></div></section><section class="panel"><h2>Who owes whom</h2><div class="balance-line"><div><strong>riya owes you</strong><p>₹200.00 awaiting your confirmation</p></div><strong class="money positive">₹860.50</strong></div><div class="balance-line"><div><strong>arjun owes you</strong><p>No pending claims</p></div><strong class="money positive">₹700.00</strong></div><div class="balance-line"><div><strong>You owe neha</strong><p>No pending claims</p></div><strong class="money negative">₹320.00</strong></div><button class="secondary wide" data-screen="settlements">Review & settle up</button><p class="note">A claimed payment stays pending until the receiver confirms it.</p></section><p class="demo-caption">${titles[theme]} · Fictional preview data</p></div></div></section>
<section class="screen" data-page="landing" hidden><div class="landing-hero"><div><h1>Good times.<br>Fair shares.</h1><p>For the trip, the flat, and the friend who always pays first. Keep shared expenses clear, right down to the last paisa.</p><button data-screen="dashboard">Start with your people <span aria-hidden="true">↗</span></button><p class="small">Equal splits, exact shares, receipts & voice.</p></div><div class="hero-art" aria-label="Illustration of an equally split café bill"><div class="orbit"></div><div class="paper"><h2>The café bill.</h2><p>Four friends. One good afternoon.</p><div class="split-row"><span>Coffee & bites</span><strong class="money">₹1,240.00</strong></div><div class="split-row"><span>Split between 4</span><strong class="money">₹310.00 each</strong></div><p>taral paid. Everyone’s share is clear.</p></div><div class="stamp" aria-hidden="true">all fair.<br>all friends.</div></div></div><div class="features"><section><span class="feature-symbol" aria-hidden="true">÷</span><h2>Your bill. Your split.</h2><p>Share equally, pick who’s in, or enter exactly what each person owes.</p></section><section><span class="feature-symbol" aria-hidden="true">▤</span><h2>Less typing. More living.</h2><p>Scan a receipt or speak an expense. Review every detail before saving.</p></section><section><span class="feature-symbol" aria-hidden="true">↔</span><h2>Settle it together.</h2><p>Record a payment claim. The receiver confirms, and the balance updates.</p></section></div></section>
<section class="screen" data-page="expense" hidden><a href="#dashboard" class="back">← Goa, with the gang</a><div class="page-head"><div><h1>Put it on the tab.</h1><p>Add an expense · Goa, with the gang</p></div></div><div class="entry-layout"><section class="panel"><div class="entry-methods"><button class="secondary" aria-pressed="true">Type it in</button><button class="secondary" data-info="Receipt flow: upload → correct items and payees → explicitly approve. This prototype does not upload files.">Scan receipt</button><button class="secondary" data-info="Voice flow: record or type → review transcript and shares → explicitly approve. This prototype does not access your microphone.">Use voice</button></div><form id="expense-form"><div class="field"><label for="description">What was it for?</label><input id="description" name="description" value="Dinner at the beach" required maxlength="200"></div><div class="two-col"><div class="field"><label for="amount">Amount (INR)</label><input id="amount" name="amount" inputmode="decimal" value="1240.00" pattern="[0-9]+([.][0-9]{1,2})?" required aria-describedby="amount-help"><small id="amount-help">Up to two decimal places.</small></div><div class="field"><label for="date">Expense date</label><input id="date" type="date" name="date" value="2026-10-30" required></div></div><div class="two-col"><div class="field"><label for="payer">Paid by</label><select id="payer"><option value="taral">taral (you)</option>riya</option>arjun</option>neha</select></div><div class="field"><label for="expense-category">Category</label><select id="expense-category"><option>Food</option><option>Travel</option><option>Stay</option><option>Shopping</option><option>Entertainment</option><option>Utilities</option><option>Other</option></select></div></div><div class="two-col"><div class="field"><label for="split">Split</label><select id="split"><option value="equal">Equally</option><option value="exact">Exact amounts</option></select></div><div class="field"><label for="tag">Tag <small>(optional)</small></label><input id="tag" placeholder="e.g. beach day"></div></div><fieldset><legend>Who’s in?</legend><p class="small">Choose participants. The payer can be outside the split.</p><div id="participants"></div></fieldset><p id="form-error" class="form-error" role="alert"></p><div class="form-actions"><button type="submit">Save preview expense</button><button type="button" class="secondary" data-screen="dashboard">Cancel</button></div></form></section><aside class="entry-aside stack"><section class="panel split-preview"><h2>Everyone’s share</h2><div id="split-preview" aria-live="polite"></div></section><p class="note">Exact to the paisa. When a split has a remainder, extra paise go to participants in member ID order.</p></aside></div></section>
<section class="screen" data-page="settlements" hidden><a href="#dashboard" class="back">← Goa, with the gang</a><div class="page-head"><div><h1>Square things up.</h1><p>Payments for Goa, with the gang</p></div></div><div class="entry-layout"><section class="stack"><article class="panel"><div class="panel-head"><h2>riya says she paid you</h2><span class="pill" id="claim-status">Awaiting you</span></div><p class="money settlement-amount">₹200.00</p><p class="small">Claimed today · “Sent after lunch”</p><p>Confirm only after you’ve received the payment.</p><div class="form-actions"><button id="confirm">Confirm received (demo)</button><button class="secondary" id="reject">Reject (demo)</button></div><p class="note" id="claim-note" role="status">Current debt: ₹860.50. This pending claim has not changed it.</p></article><article class="panel"><h2>Record a payment you made</h2><p class="small">To neha · You owe ₹320.00 in this group</p><form id="payment-form"><div class="two-col"><div class="field"><label for="payment">Amount (INR)</label><input id="payment" inputmode="decimal" value="320.00" required pattern="[0-9]+([.][0-9]{1,2})?"></div><div class="field"><label for="payment-note">Note <small>(optional)</small></label><input id="payment-note" placeholder="How did you pay?"></div></div><p class="small" id="available">Available to claim: ₹320.00 · Pending: ₹0.00</p><p class="form-error" id="payment-error" role="alert"></p><button id="claim-submit">Record payment claim (demo)</button><p class="note" id="payment-state" role="status">This records a claim. neha must confirm receipt before your balance changes.</p></form></article></section><aside class="stack"><article class="panel"><h2>Clear, on both sides.</h2><p>A payment claim is a request to confirm a payment that already happened.</p><p class="note">BroYouOweMe keeps the record. No money moves through this app.</p></article></aside></div></section>
</main><footer><span>Shared plans. Fair shares. Still friends.</span><span>${titles[theme]} · HTML prototype · INR only</span></footer></div><div class="toast" role="status" hidden></div>`;
const people=['taral','riya','arjun','neha'];
let expenses=[{description:'Dinner at the beach',payer:'taral',category:'Food',amount:248050,icon:'◒',share:'Equal split · 4 people'},{description:'The little villa in Anjuna',payer:'neha',category:'Stay',amount:960000,icon:'⌂',share:'Exact shares'},{description:'Scooters for the weekend',payer:'arjun',category:'Travel',amount:180000,icon:'↗',share:'Equal split · 4 people'},{description:'Coffee before the drive',payer:'riya',category:'Food',amount:62000,icon:'◡',share:'Equal split · 3 people'}];
const money=n=>'₹'+(Math.floor(n/100)).toLocaleString('en-IN')+'.'+String(n%100).padStart(2,'0');
function parseMoney(value){if(!/^\d+(\.\d{1,2})?$/.test(value))return null;const [r,p='']=value.split('.');const n=Number(r)*100+Number(p.padEnd(2,'0'));return Number.isSafeInteger(n)&&n>0?n:null}
function escapeHtml(s){const el=document.createElement('span');el.textContent=s;return el.innerHTML}
function renderExpenses(){const q=document.querySelector('#search').value.toLowerCase();const cat=document.querySelector('#category-filter').value;const rows=expenses.filter(e=>e.description.toLowerCase().includes(q)&&(!cat||e.category===cat));document.querySelector('#expenses').innerHTML=rows.map(e=>`<li><div class="receipt-title"><span class="category-icon" aria-hidden="true">${e.icon}</span><div><strong>${escapeHtml(e.description)}</strong><small>${escapeHtml(e.payer)} paid · ${e.category}</small></div></div><div class="amount money">${money(e.amount)}<small>${e.share}</small></div></li>`).join('');document.querySelector('#no-results').hidden=rows.length>0}
let timeout;function toast(text){const t=document.querySelector('.toast');t.textContent=text;t.hidden=false;clearTimeout(timeout);timeout=setTimeout(()=>t.hidden=true,5000)}
function show(screen,focus=true){if(screen==='history'){screen='dashboard';document.querySelector('.panel-head h2').textContent='Expense history'}else document.querySelector('.panel-head h2').textContent='Recent expenses';document.querySelectorAll('.screen').forEach(p=>p.hidden=p.dataset.page!==screen);document.querySelectorAll('.prototype-nav button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.screen===screen)));document.title=titles[theme]+' · '+({dashboard:'Goa group',landing:'Good times. Fair shares.',expense:'Add expense',settlements:'Settle up'}[screen]);if(focus){document.querySelector('#main').focus({preventScroll:true});window.scrollTo(0,0)}}
document.querySelectorAll('[data-screen]').forEach(b=>b.addEventListener('click',()=>{location.hash=b.dataset.screen}));document.querySelectorAll('[data-info]').forEach(b=>b.addEventListener('click',()=>toast(b.dataset.info)));window.addEventListener('hashchange',()=>show(['dashboard','landing','expense','settlements','history'].includes(location.hash.slice(1))?location.hash.slice(1):'dashboard'));
document.querySelector('#participants').innerHTML=people.map((p,i)=>`<label class="participant"><input type="checkbox" value="${p}" checked><span class="avatar" aria-hidden="true">${p.slice(0,2).toUpperCase()}</span><span>${p}${i===0?' (you)':''}</span><input class="share" aria-label="Exact share for ${p} in INR" inputmode="decimal" value="310.00" hidden></label>`).join('');
function allocation(){const selected=[...document.querySelectorAll('.participant')].filter(r=>r.querySelector('[type=checkbox]').checked);const amount=parseMoney(document.querySelector('#amount').value);const exact=document.querySelector('#split').value==='exact';return{selected,amount,exact,shares:selected.map((r,i)=>({name:r.querySelector('[type=checkbox]').value,amount:exact?(parseMoney(r.querySelector('.share').value)??0):amount?Math.floor(amount/selected.length)+(i<amount%selected.length?1:0):0}))}}
function updateSplit(){const a=allocation();document.querySelectorAll('.participant').forEach(r=>{r.querySelector('.share').hidden=!a.exact||!r.querySelector('[type=checkbox]').checked});const sum=a.shares.reduce((n,p)=>n+p.amount,0);document.querySelector('#split-preview').innerHTML=a.shares.map(p=>`<div class="split-row"><span>${p.name}</span><strong class="money">${money(p.amount)}</strong></div>`).join('')+`<div class="split-row split-total"><span>Total allocated</span><span class="money">${money(sum)}</span></div><p class="small">${!a.selected.length?'Choose at least one participant.':sum===a.amount?'Every paisa accounted for.':'Allocation must match the expense total.'}</p>`}
document.querySelector('#expense-form').addEventListener('input',updateSplit);document.querySelector('#expense-form').addEventListener('change',updateSplit);
document.querySelector('#expense-form').addEventListener('submit',e=>{e.preventDefault();const a=allocation();const err=document.querySelector('#form-error');if(!a.amount||!a.selected.length||a.shares.reduce((n,p)=>n+p.amount,0)!==a.amount){err.textContent='Enter a valid amount, select participants, and make shares match the total.';return}err.textContent='';expenses.unshift({description:document.querySelector('#description').value,payer:document.querySelector('#payer').value,category:document.querySelector('#expense-category').value,amount:a.amount,icon:'＋',share:a.exact?'Exact shares':'Equal split · '+a.selected.length+' people'});document.querySelector('#search').value='';document.querySelector('#category-filter').value='';renderExpenses();location.hash='dashboard';toast('Added to this preview. Summary balances remain illustrative. Nothing was saved to the app.')});
document.querySelector('#search').addEventListener('input',renderExpenses);document.querySelector('#category-filter').addEventListener('change',renderExpenses);
for(const action of ['confirm','reject'])document.querySelector('#'+action).addEventListener('click',()=>{document.querySelector('#claim-status').textContent=action==='confirm'?'Confirmed (demo)':'Rejected (demo)';document.querySelector('#claim-note').textContent=action==='confirm'?'Preview result: riya’s debt would become ₹660.50. No real ledger was changed.':'Preview result: riya’s debt remains ₹860.50. No real ledger was changed.';document.querySelector('#confirm').disabled=true;document.querySelector('#reject').disabled=true});
document.querySelector('#payment-form').addEventListener('submit',e=>{e.preventDefault();const n=parseMoney(document.querySelector('#payment').value);if(!n||n>32000){document.querySelector('#payment-error').textContent='Enter an amount from ₹0.01 to ₹320.00.';return}document.querySelector('#payment-error').textContent='';document.querySelector('#available').textContent='Available to claim: '+money(32000-n)+' · Pending: '+money(n);document.querySelector('#payment-state').textContent='Preview claim awaiting neha’s confirmation. The ₹320.00 debt is unchanged. Nothing was sent or saved.';document.querySelector('#claim-submit').disabled=true});
renderExpenses();updateSplit();show(['landing','expense','settlements','history'].includes(location.hash.slice(1))?location.hash.slice(1):'dashboard',false);
